package com.gravecost;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import lombok.Getter;
import lombok.Setter;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

/**
 * Minimal 3-column text table for overlay panels (RuneLite core no longer ships one).
 * Column 1 is left-aligned, columns 2 and 3 right-aligned. "Span" rows are a single
 * left-aligned cell (headings, item names) that don't widen the label column.
 *
 * Text widths are measured once per font, so steady-state rendering allocates nothing.
 */
class ColumnsComponent implements LayoutableRenderableEntity
{
	private static final int GAP = 12;

	static final class Cell
	{
		final String text;
		final Color color;

		Cell(String text, Color color)
		{
			this.text = text == null ? "" : text;
			this.color = color == null ? Color.WHITE : color;
		}
	}

	static Cell cell(String text, Color color)
	{
		return new Cell(text, color);
	}

	static Cell cell(String text)
	{
		return new Cell(text, Color.WHITE);
	}

	/** A span row has a single cell; a normal row has three. */
	private final List<Cell[]> rows = new ArrayList<>();

	@Setter
	private Point preferredLocation = new Point();

	@Setter
	private Dimension preferredSize = new Dimension(ComponentConstants.STANDARD_WIDTH, 0);

	@Getter
	private final Rectangle bounds = new Rectangle();

	// Cached layout, recomputed only when rows are added or the overlay font changes
	private final int[] colWidths = new int[3];
	private int spanWidth;
	private int[][] cellWidths;
	private Font measuredFont;
	private final Dimension size = new Dimension();

	void addRow(Cell left, Cell mid, Cell right)
	{
		rows.add(new Cell[]{left, mid, right});
		measuredFont = null;
	}

	void addSpan(Cell text)
	{
		rows.add(new Cell[]{text});
		measuredFont = null;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		FontMetrics fm = graphics.getFontMetrics();
		if (fm.getFont() != measuredFont)
		{
			measure(fm);
		}

		int width = Math.max(preferredSize.width,
			Math.max(spanWidth, colWidths[0] + GAP + colWidths[1] + GAP + colWidths[2]));
		int x = preferredLocation.x;
		int y = preferredLocation.y;
		int rightEdge = x + width;
		int midEdge = rightEdge - colWidths[2] - GAP;

		for (int r = 0; r < rows.size(); r++)
		{
			Cell[] row = rows.get(r);
			int baseline = y + fm.getAscent();
			draw(graphics, row[0], x, baseline);
			if (row.length == 3)
			{
				draw(graphics, row[1], midEdge - cellWidths[r][1], baseline);
				draw(graphics, row[2], rightEdge - cellWidths[r][2], baseline);
			}
			y += fm.getHeight();
		}

		size.setSize(width, y - preferredLocation.y);
		bounds.setLocation(preferredLocation);
		bounds.setSize(size);
		return size;
	}

	private void measure(FontMetrics fm)
	{
		measuredFont = fm.getFont();
		cellWidths = new int[rows.size()][3];
		colWidths[0] = colWidths[1] = colWidths[2] = 0;
		spanWidth = 0;
		for (int r = 0; r < rows.size(); r++)
		{
			Cell[] row = rows.get(r);
			if (row.length == 1)
			{
				spanWidth = Math.max(spanWidth, fm.stringWidth(row[0].text));
				continue;
			}
			for (int c = 0; c < 3; c++)
			{
				int w = fm.stringWidth(row[c].text);
				cellWidths[r][c] = w;
				colWidths[c] = Math.max(colWidths[c], w);
			}
		}
	}

	private static void draw(Graphics2D g, Cell cell, int x, int baseline)
	{
		if (cell.text.isEmpty())
		{
			return;
		}
		g.setColor(Color.BLACK);
		g.drawString(cell.text, x + 1, baseline + 1);
		g.setColor(cell.color);
		g.drawString(cell.text, x, baseline);
	}
}

package com.gravecost;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

/**
 * Pure fee math, no RuneLite types, so it can be unit-tested on its own.
 *
 * Rules (OSRS wiki, "Death/Item Recovery Fees" + "Items Kept on Death"):
 *  - Keep the 3 most valuable items (0 if skulled); Protect Item adds 1 more.
 *  - Grave fee is charged PER reclaimed item, by that item's value:
 *        < 100k        : free
 *        100k  - < 1m  : 1,000
 *        1m    - < 10m : 10,000
 *        >= 10m        : 100,000
 *    Total grave fee is capped at 500,000.
 *  - Death's Office (after the 15 min grave timer): 5% of each item worth >= 100k, no cap.
 *  - Ironmen pay 50% of both.
 *
 * Assumptions: a stack counts as one reclaimed item valued at (unit price x quantity);
 * kept-item selection works on individual units ranked by unit price.
 */
public final class DeathCostCalculator
{
	public static final long FREE_THRESHOLD = 100_000L;
	public static final long GRAVE_FEE_CAP = 500_000L;
	public static final int BASE_KEPT = 3;

	private DeathCostCalculator()
	{
	}

	public static final class Entry
	{
		public final int itemId;
		public final String name;
		public final int quantity;
		public final long unitPrice;

		public Entry(int itemId, String name, int quantity, long unitPrice)
		{
			this.itemId = itemId;
			this.name = name;
			this.quantity = quantity;
			this.unitPrice = unitPrice;
		}

		public long stackValue()
		{
			return unitPrice * quantity;
		}
	}

	/** One lost item and what it contributes to each fee (ironman discount already applied). */
	public static final class LostItem
	{
		public final Entry entry;
		public final long graveFee;
		public final long deathsOfficeFee;

		LostItem(Entry entry, long graveFee, long deathsOfficeFee)
		{
			this.entry = entry;
			this.graveFee = graveFee;
			this.deathsOfficeFee = deathsOfficeFee;
		}
	}

	public static final class Result
	{
		public final int keepSlots;
		public final List<Entry> kept;
		/** Lost items, most valuable first, each with its fee contribution. */
		public final List<LostItem> lost;
		public final long keptValue;
		public final long lostValue;
		public final long graveFee;
		public final boolean graveFeeCapped;
		public final long deathsOfficeFee;

		Result(int keepSlots, List<Entry> kept, List<LostItem> lost, long keptValue, long lostValue,
			long graveFee, boolean graveFeeCapped, long deathsOfficeFee)
		{
			this.keepSlots = keepSlots;
			this.kept = kept;
			this.lost = lost;
			this.keptValue = keptValue;
			this.lostValue = lostValue;
			this.graveFee = graveFee;
			this.graveFeeCapped = graveFeeCapped;
			this.deathsOfficeFee = deathsOfficeFee;
		}
	}

	public static int keepSlots(boolean skulled, boolean protectItem)
	{
		return (skulled ? 0 : BASE_KEPT) + (protectItem ? 1 : 0);
	}

	public static long graveFeeFor(long itemValue)
	{
		if (itemValue < FREE_THRESHOLD)
		{
			return 0L;
		}
		if (itemValue < 1_000_000L)
		{
			return 1_000L;
		}
		if (itemValue < 10_000_000L)
		{
			return 10_000L;
		}
		return 100_000L;
	}

	public static long deathsOfficeFeeFor(long itemValue)
	{
		return itemValue >= FREE_THRESHOLD ? itemValue * 5 / 100 : 0L;
	}

	/**
	 * @param items     every item in equipment + inventory, in game order (ties keep the earlier one)
	 * @param keepSlots result of {@link #keepSlots}
	 * @param ironman   apply the 50% ironman discount
	 */
	public static Result calculate(List<Entry> items, int keepSlots, boolean ironman)
	{
		// Stable sort by unit price, most valuable first
		List<Entry> sorted = new ArrayList<>(items);
		Collections.sort(sorted, Comparator.comparingLong((Entry e) -> e.unitPrice).reversed());

		List<Entry> kept = new ArrayList<>();
		List<Entry> lost = new ArrayList<>();
		int slotsLeft = keepSlots;
		long keptValue = 0L;

		for (Entry e : sorted)
		{
			if (e.quantity <= 0)
			{
				continue;
			}
			int keepQty = Math.min(slotsLeft, e.quantity);
			slotsLeft -= keepQty;
			if (keepQty > 0)
			{
				kept.add(new Entry(e.itemId, e.name, keepQty, e.unitPrice));
				keptValue += e.unitPrice * keepQty;
			}
			int lostQty = e.quantity - keepQty;
			if (lostQty > 0)
			{
				lost.add(new Entry(e.itemId, e.name, lostQty, e.unitPrice));
			}
		}

		long lostValue = 0L;
		long graveFee = 0L;
		long officeFee = 0L;
		List<LostItem> lostItems = new ArrayList<>();
		for (Entry e : lost)
		{
			long v = e.stackValue();
			long g = graveFeeFor(v);
			long o = deathsOfficeFeeFor(v);
			lostValue += v;
			graveFee += g;
			officeFee += o;
			lostItems.add(new LostItem(e, ironman ? g / 2 : g, ironman ? o / 2 : o));
		}

		boolean capped = graveFee > GRAVE_FEE_CAP;
		graveFee = Math.min(graveFee, GRAVE_FEE_CAP);

		if (ironman)
		{
			graveFee /= 2;
			officeFee /= 2;
		}

		return new Result(keepSlots, kept, lostItems, keptValue, lostValue, graveFee, capped, officeFee);
	}
}

package com.gravecost;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(GraveCostConfig.GROUP)
public interface GraveCostConfig extends Config
{
	String GROUP = "gravecost";

	@ConfigItem(
		keyName = "ironman",
		name = "Ironman discount",
		description = "Apply the 50% ironman discount to reclaim fees",
		position = 0
	)
	default boolean ironman()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showDeathsOffice",
		name = "Show Death's Office fee",
		description = "Also show the fee if the grave expires and items go to Death's Office (5%)",
		position = 1
	)
	default boolean showDeathsOffice()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showKeptItems",
		name = "List kept items",
		description = "List which items would be kept on death",
		position = 2
	)
	default boolean showKeptItems()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showBreakdown",
		name = "Show fee breakdown",
		description = "Itemize which lost items make up the fee totals",
		position = 3
	)
	default boolean showBreakdown()
	{
		return true;
	}

	@ConfigItem(
		keyName = "onlyInBank",
		name = "Only show in bank",
		description = "Only show the overlay while the bank interface is open",
		position = 4
	)
	default boolean onlyInBank()
	{
		return false;
	}

	@ConfigItem(
		keyName = "hideWhenFree",
		name = "Hide when free",
		description = "Hide the overlay when reclaiming from the grave would cost nothing, even without Protect Item",
		position = 5
	)
	default boolean hideWhenFree()
	{
		return false;
	}
}

package com.gravecost;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

/**
 * Renders the plugin's pre-built {@link GraveCostSnapshot}. Runs every frame, so it does
 * nothing but visibility checks and re-adding already-built components.
 *
 *   Grave Cost      3 kept   4 kept
 *   Kept value        1.0B     1.0B
 *   At risk          6.3M     1.3M
 *   Grave fee          12K       2K
 *   Death's Office    315K      65K
 */
class GraveCostOverlay extends OverlayPanel
{
	private final GraveCostPlugin plugin;

	@Inject
	GraveCostOverlay(GraveCostPlugin plugin)
	{
		super(plugin);
		this.plugin = plugin;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		GraveCostSnapshot snapshot = plugin.getSnapshot();
		if (snapshot == null
			|| (plugin.isHideWhenFree() && snapshot.free)
			|| (plugin.isOnlyInBank() && !plugin.isBankOpen()))
		{
			return null;
		}

		for (LayoutableRenderableEntity component : snapshot.components)
		{
			panelComponent.getChildren().add(component);
		}
		return super.render(graphics);
	}
}

package com.gravecost;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import lombok.AccessLevel;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * All data comes from RuneLite's in-memory caches: item definitions from the game cache and
 * prices from ItemManager's price map (which RuneLite itself refreshes in bulk). This plugin
 * makes no network requests.
 *
 * Work is event-driven: item lookups and fee math only run on the first game tick after the
 * inventory/equipment, skull, or config changes, plus a cheap periodic refresh so the numbers
 * follow RuneLite's own price updates.
 */
@PluginDescriptor(
	name = "Grave Cost",
	description = "Shows what it would cost to reclaim your current gear and inventory from a grave or Death's Office",
	tags = {"death", "grave", "gravestone", "reclaim", "risk", "cost", "protect item"}
)
public class GraveCostPlugin extends Plugin
{
	// ~5 minutes; RuneLite refreshes its price map far less often than this
	private static final int PRICE_REFRESH_TICKS = 500;

	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private GraveCostOverlay overlay;

	@Inject
	private GraveCostConfig config;

	@Getter(AccessLevel.PACKAGE)
	private GraveCostSnapshot snapshot;

	// Config cached here so the per-frame overlay never goes through the config proxy
	@Getter(AccessLevel.PACKAGE)
	private boolean onlyInBank;
	@Getter(AccessLevel.PACKAGE)
	private boolean hideWhenFree;
	private boolean ironman;
	private boolean showDeathsOffice;
	private boolean showBreakdown;
	private boolean showKeptItems;

	private DeathCostCalculator.Result result;
	private DeathCostCalculator.Result resultProtect;
	private boolean skulled;
	private boolean protectItem;

	private boolean itemsDirty = true;
	private int ticksSinceRecalc;

	@Provides
	GraveCostConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GraveCostConfig.class);
	}

	@Override
	protected void startUp()
	{
		loadConfig();
		itemsDirty = true;
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		clear();
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		if (id == InventoryID.INV || id == InventoryID.WORN)
		{
			itemsDirty = true;
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (GraveCostConfig.GROUP.equals(event.getGroup()))
		{
			loadConfig();
			// Ironman changes the fees; display toggles only need a snapshot rebuild, but a full
			// recalc is cheap and config changes are rare.
			itemsDirty = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			clear();
			return;
		}

		Player local = client.getLocalPlayer();
		boolean nowSkulled = local != null && local.getSkullIcon() != -1;
		// Normal prayer book, or the Ruinous Powers (Leagues) version
		boolean nowProtect = client.getVarbitValue(VarbitID.PRAYER_PROTECTITEM) == 1
			|| client.getVarbitValue(VarbitID.PRAYER_PROTECT_ITEM_R) == 1;

		boolean recalc = itemsDirty || nowSkulled != skulled || ++ticksSinceRecalc >= PRICE_REFRESH_TICKS;
		boolean rebuild = recalc || nowProtect != protectItem || snapshot == null;

		skulled = nowSkulled;
		protectItem = nowProtect;

		if (recalc)
		{
			recalculate();
		}
		if (rebuild && result != null)
		{
			// Protect Item toggles only move the highlight, so they skip the item lookups
			snapshot = GraveCostSnapshot.build(result, resultProtect, skulled, protectItem,
				showDeathsOffice, showBreakdown, showKeptItems);
		}
	}

	/** Bank interface is open and visible. */
	boolean isBankOpen()
	{
		Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		return bank != null && !bank.isHidden();
	}

	private void loadConfig()
	{
		onlyInBank = config.onlyInBank();
		hideWhenFree = config.hideWhenFree();
		ironman = config.ironman();
		showDeathsOffice = config.showDeathsOffice();
		showBreakdown = config.showBreakdown();
		showKeptItems = config.showKeptItems();
	}

	private void clear()
	{
		snapshot = null;
		result = null;
		resultProtect = null;
		itemsDirty = true;
	}

	private void recalculate()
	{
		List<DeathCostCalculator.Entry> entries = new ArrayList<>(40);
		addContainer(entries, client.getItemContainer(InventoryID.WORN));
		addContainer(entries, client.getItemContainer(InventoryID.INV));

		result = DeathCostCalculator.calculate(entries, DeathCostCalculator.keepSlots(skulled, false), ironman);
		resultProtect = DeathCostCalculator.calculate(entries, DeathCostCalculator.keepSlots(skulled, true), ironman);

		itemsDirty = false;
		ticksSinceRecalc = 0;
	}

	private void addContainer(List<DeathCostCalculator.Entry> out, ItemContainer container)
	{
		if (container == null)
		{
			return;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() <= 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			int id = itemManager.canonicalize(item.getId());
			ItemComposition comp = itemManager.getItemComposition(id);

			// Cached GE price; items with no GE value fall back to high alch (matches how the game ranks them)
			long price = itemManager.getItemPrice(id);
			if (price <= 0)
			{
				price = comp.getHaPrice();
			}
			out.add(new DeathCostCalculator.Entry(id, comp.getName(), item.getQuantity(), price));
		}
	}
}

package com.gravecost;

import static com.gravecost.ColumnsComponent.cell;

import java.awt.Color;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Immutable, pre-formatted overlay content. Built only when something changes
 * (items, skull, Protect Item, config); the overlay just re-adds these two components
 * every frame, so rendering does no math, matching or string formatting.
 *
 * Everything below the title is one {@link ColumnsComponent}, so the fee columns of the
 * summary and both breakdowns line up.
 */
final class GraveCostSnapshot
{
	private static final Color FREE = new Color(0, 200, 83);
	private static final Color COST = new Color(255, 152, 0);
	private static final Color ACTIVE = Color.YELLOW;
	private static final Color INACTIVE = Color.GRAY;
	private static final ColumnsComponent.Cell BLANK = cell("");

	/** True when the 3-kept grave fee is 0 (used by "Hide when free"). */
	final boolean free;
	final List<LayoutableRenderableEntity> components;

	private GraveCostSnapshot(boolean free, List<LayoutableRenderableEntity> components)
	{
		this.free = free;
		this.components = components;
	}

	static GraveCostSnapshot build(DeathCostCalculator.Result base, DeathCostCalculator.Result pi,
		boolean skulled, boolean protectItem, boolean showDeathsOffice, boolean showBreakdown, boolean showKeptItems)
	{
		TitleComponent title = TitleComponent.builder()
			.text("Grave Cost" + (skulled ? " (skulled)" : ""))
			.build();

		ColumnsComponent table = new ColumnsComponent();
		table.addRow(BLANK,
			cell(base.keepSlots + " kept", protectItem ? INACTIVE : ACTIVE),
			cell(pi.keepSlots + " kept", protectItem ? ACTIVE : INACTIVE));
		table.addRow(cell("Kept value"), cell(gp(base.keptValue)), cell(gp(pi.keptValue)));
		table.addRow(cell("At risk"), cell(gp(base.lostValue)), cell(gp(pi.lostValue)));
		table.addRow(cell("Grave fee"), fee(base.graveFee, base.graveFeeCapped), fee(pi.graveFee, pi.graveFeeCapped));
		if (showDeathsOffice)
		{
			table.addRow(cell("Death's Office"), fee(base.deathsOfficeFee, false), fee(pi.deathsOfficeFee, false));
		}

		if (showBreakdown && !base.lost.isEmpty())
		{
			List<DeathCostCalculator.LostItem> matches = matchProtectItem(base, pi);
			addBreakdown(table, "Grave fee breakdown", base, pi, matches, true);
			if (showDeathsOffice)
			{
				addBreakdown(table, "Death's Office breakdown", base, pi, matches, false);
			}
		}

		if (showKeptItems && !pi.kept.isEmpty())
		{
			table.addSpan(BLANK);
			table.addSpan(cell("Kept items"));
			// The 4-kept list is the 3-kept list plus one more unit, so show it once and tag the extra item
			int unitsBefore = 0;
			for (DeathCostCalculator.Entry e : pi.kept)
			{
				boolean piOnly = unitsBefore + e.quantity > base.keepSlots;
				unitsBefore += e.quantity;
				table.addSpan(cell("  " + e.name + (e.quantity > 1 ? " x" + e.quantity : "")
					+ (piOnly ? " (PI)" : ""), Color.LIGHT_GRAY));
			}
		}

		return new GraveCostSnapshot(base.graveFee == 0,
			Collections.unmodifiableList(Arrays.asList(title, table)));
	}

	/**
	 * For each 3-kept lost item, the same item in the 4-kept result, or null if Protect Item saves it.
	 */
	private static List<DeathCostCalculator.LostItem> matchProtectItem(DeathCostCalculator.Result base,
		DeathCostCalculator.Result pi)
	{
		List<DeathCostCalculator.LostItem> remaining = new ArrayList<>(pi.lost);
		List<DeathCostCalculator.LostItem> matches = new ArrayList<>(base.lost.size());
		for (DeathCostCalculator.LostItem item : base.lost)
		{
			DeathCostCalculator.LostItem match = null;
			for (Iterator<DeathCostCalculator.LostItem> it = remaining.iterator(); it.hasNext(); )
			{
				DeathCostCalculator.LostItem candidate = it.next();
				if (candidate.entry.itemId == item.entry.itemId)
				{
					match = candidate;
					it.remove();
					break;
				}
			}
			matches.add(match);
		}
		return matches;
	}

	/** One row per lost item that costs something; items under 100k roll up into one "free" row. */
	private static void addBreakdown(ColumnsComponent table, String title,
		DeathCostCalculator.Result base, DeathCostCalculator.Result pi,
		List<DeathCostCalculator.LostItem> matches, boolean grave)
	{
		table.addSpan(BLANK);
		table.addSpan(cell(title));

		int freeCount = 0;
		for (int i = 0; i < base.lost.size(); i++)
		{
			DeathCostCalculator.LostItem item = base.lost.get(i);
			long baseFee = grave ? item.graveFee : item.deathsOfficeFee;
			if (baseFee == 0)
			{
				freeCount++;
				continue;
			}

			DeathCostCalculator.LostItem match = matches.get(i);
			ColumnsComponent.Cell piCell = match == null
				? cell("kept", FREE)
				: fee(grave ? match.graveFee : match.deathsOfficeFee, false);

			String name = "  " + item.entry.name
				+ (item.entry.quantity > 1 ? " x" + gp(item.entry.quantity) : "");
			table.addRow(cell(name, Color.LIGHT_GRAY), fee(baseFee, false), piCell);
		}

		if (freeCount > 0)
		{
			table.addRow(cell("  " + freeCount + " item" + (freeCount == 1 ? "" : "s") + " < 100K", Color.GRAY),
				cell("free", FREE), cell("free", FREE));
		}

		if (grave && (base.graveFeeCapped || pi.graveFeeCapped))
		{
			table.addRow(cell("  Capped at", Color.GRAY),
				cell(base.graveFeeCapped ? gp(base.graveFee) : ""),
				cell(pi.graveFeeCapped ? gp(pi.graveFee) : ""));
		}
	}

	private static ColumnsComponent.Cell fee(long value, boolean capped)
	{
		return cell(gp(value) + (capped ? " (cap)" : ""), value == 0 ? FREE : COST);
	}

	/** Compact gp with up to 3 significant digits: 950, 1K, 22.5K, 1.15M, 1.2B. Integer math only. */
	static String gp(long value)
	{
		if (value < 1_000)
		{
			return Long.toString(value);
		}
		// Thresholds sit at x99.5 so rounding never prints "1000K"
		if (value < 999_500)
		{
			return scaled(value, 1_000L) + "K";
		}
		if (value < 999_500_000)
		{
			return scaled(value, 1_000_000L) + "M";
		}
		return scaled(value, 1_000_000_000L) + "B";
	}

	private static String scaled(long value, long div)
	{
		long whole = value / div;
		if (whole >= 100)
		{
			return Long.toString((value + div / 2) / div);
		}
		if (whole >= 10)
		{
			long tenths = (value * 10 + div / 2) / div;
			return tenths % 10 == 0 ? Long.toString(tenths / 10) : (tenths / 10) + "." + (tenths % 10);
		}
		long hundredths = (value * 100 + div / 2) / div;
		long frac = hundredths % 100;
		if (frac == 0)
		{
			return Long.toString(hundredths / 100);
		}
		return (hundredths / 100) + "." + (frac % 10 == 0 ? Long.toString(frac / 10) : (frac < 10 ? "0" + frac : Long.toString(frac)));
	}
}

package com.gravecost;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class DeathCostCalculatorTest
{
	private static DeathCostCalculator.Entry e(String name, int qty, long price)
	{
		return new DeathCostCalculator.Entry(0, name, qty, price);
	}

	@Test
	public void keepSlots()
	{
		assertEquals(3, DeathCostCalculator.keepSlots(false, false));
		assertEquals(4, DeathCostCalculator.keepSlots(false, true));
		assertEquals(0, DeathCostCalculator.keepSlots(true, false));
		assertEquals(1, DeathCostCalculator.keepSlots(true, true));
	}

	@Test
	public void feeTiers()
	{
		assertEquals(0, DeathCostCalculator.graveFeeFor(99_999));
		assertEquals(1_000, DeathCostCalculator.graveFeeFor(100_000));
		assertEquals(10_000, DeathCostCalculator.graveFeeFor(1_000_000));
		assertEquals(100_000, DeathCostCalculator.graveFeeFor(10_000_000));
		assertEquals(5_000, DeathCostCalculator.deathsOfficeFeeFor(100_000));
		assertEquals(0, DeathCostCalculator.deathsOfficeFeeFor(99_999));
	}

	@Test
	public void keepsMostValuableAndChargesTheRest()
	{
		List<DeathCostCalculator.Entry> items = Arrays.asList(
			e("Shadow", 1, 1_000_000_000L),
			e("Fang", 1, 20_000_000L),
			e("Torva helm", 1, 15_000_000L),
			e("Masori body", 1, 5_000_000L),   // lost: 10k
			e("Ring", 1, 500_000L),            // lost: 1k
			e("Sharks", 20, 1_000L),           // lost stack 20k: free
			e("Blood runes", 2_000, 400L)      // lost stack 800k: 1k
		);
		DeathCostCalculator.Result r = DeathCostCalculator.calculate(items, 3, false);
		assertEquals(3, r.kept.size());
		assertEquals(5_000_000L + 500_000L + 20_000L + 800_000L, r.lostValue);
		assertEquals(12_000L, r.graveFee);
		assertEquals(250_000L + 25_000L + 40_000L, r.deathsOfficeFee);

		// Itemized fees add up to the total, most valuable first
		assertEquals(4, r.lost.size());
		assertEquals(10_000L, r.lost.get(0).graveFee);       // Masori body
		assertEquals(250_000L, r.lost.get(0).deathsOfficeFee);
		long sum = 0;
		for (DeathCostCalculator.LostItem li : r.lost)
		{
			sum += li.graveFee;
		}
		assertEquals(r.graveFee, sum);

		// Protect Item saves the Masori body too
		DeathCostCalculator.Result pi = DeathCostCalculator.calculate(items, 4, false);
		assertEquals(2_000L, pi.graveFee);

		// Ironman halves
		assertEquals(6_000L, DeathCostCalculator.calculate(items, 3, true).graveFee);
	}

	@Test
	public void graveFeeCapped()
	{
		List<DeathCostCalculator.Entry> items = Arrays.asList(
			e("A", 1, 50_000_000L), e("B", 1, 50_000_000L), e("C", 1, 50_000_000L),
			e("D", 1, 50_000_000L), e("E", 1, 50_000_000L), e("F", 1, 50_000_000L));
		DeathCostCalculator.Result r = DeathCostCalculator.calculate(items, 0, false);
		assertEquals(500_000L, r.graveFee);
		assertTrue(r.graveFeeCapped);
	}
}

